515	// Acceptance test for the change request:
516	//   "On the home screen show me my top five clients. Rank them by how much they owe."
517	//
518	// The home screen is the dashboard (reached from the nav, dashboard-page — the same place the owed
519	// total and the overdue count live; see dashboard.spec and dashboard-overdue.spec). It gains a new
520	// region that lists the user's TOP FIVE CLIENTS, ranked by HOW MUCH EACH CLIENT OWES, most first.
521	// Its anchors:
522	//   - dashboard-top-clients          — the region that surfaces the list
523	//   - dashboard-top-clients-loading  — shown while the list's data is being fetched
524	//   - dashboard-top-clients-error    — shown instead of the list when that data cannot be loaded
525	//   - top-client-row-<clientId>      — one row per listed client, keyed by the client's id
526	//   - top-client-name                — that client's name, in the row
527	//   - top-client-amount              — how much that client owes, in the row
528	//
529	// WHAT "OWES" MEANS. "How much they owe" is the client's outstanding balance — exactly the figure the
530	// app already works out per client (client-statement.spec's client-outstanding-total, and client-sort
531	// .spec's "by how much they owe" ordering): the sum, across the client's invoices, of each invoice's
532	// net total minus what has been paid against it. The seeds below keep this unambiguous the same way
533	// client-sort.spec does — every invoice is SENT, so whether the roll-up counts drafts never arises —
534	// and the net-of-payments test uses payments (which reduce what is owed on every surface) to prove the
535	// ranking is on what is STILL owed, not on the gross amount invoiced.
536	//
537	// "TOP FIVE" means: of all the clients, the FIVE who owe the most are listed (a sixth, who owes less,
538	// is dropped), and they are shown most-owed FIRST. The seeded owed amounts are all distinct so the
539	// ranking — both which five are chosen and the order they appear in — is unambiguous.
540	//
541	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
542	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId },
543	// `invoices` honours { id, amount, projectId, status } and `payments` honours
544	// { id, invoiceId, amount, date }. This change surfaces no audit records, so there is nothing to
545	// assert on the audit channel.
546	import { test, expect, type Page, type Locator } from '@playwright/test';
547	import { resetAndSeed } from '../support/seed';
548	
549	// A client's owed amount may be rendered bare (300) or dressed up as money ("$300.00"). Assert the
550	// cell CARRIES the expected number as a standalone token, so the test binds to the meaning rather
551	// than to one presentation. The surrounding (^|\D)…(\D|$) keeps a smaller number from matching inside
552	// a larger one (100 must not satisfy a check inside 1000, nor 50 inside 500). Every figure below stays
553	// under a thousand, so thousands grouping never arises.
554	const asToken = (n: number) => new RegExp(`(^|\\D)${n}(\\D|$)`);
555	
556	const topRows = (page: Page): Locator => page.locator('[data-testid^="top-client-row-"]');
557	const topRow = (page: Page, clientId: number): Locator =>
558	  page.getByTestId(`top-client-row-${clientId}`);
559	const nameCell = (page: Page, clientId: number): Locator =>
560	  topRow(page, clientId).getByTestId('top-client-name');
561	const amountCell = (page: Page, clientId: number): Locator =>
562	  topRow(page, clientId).getByTestId('top-client-amount');
563	
564	// The client ids of the top-client rows in the order the DOM renders them (top to bottom).
565	async function rowOrder(page: Page): Promise<number[]> {
566	  return topRows(page).evaluateAll((els) =>
567	    els.map((el) => Number(el.getAttribute('data-testid')!.replace('top-client-row-', ''))),
568	  );
569	}
