821	// Acceptance test for the change request:
822	//   "The money I am owed should only count invoices I have actually sent. Do not count drafts."
823	//
824	// The dashboard's "money owed" figure (dashboard-outstanding-total) is the sum of the invoices I
825	// have actually SENT and not yet been paid for. An invoice moves through DRAFT -> SENT -> PAID
826	// (see invoice-send.spec). A DRAFT has not been sent, so it is NOT money I am owed and must not be
827	// counted; a PAID invoice has been settled, so it is not owed either. Only SENT invoices count.
828	//
829	// This is a change to how the owed total is computed: before it, an unsent draft would have been
830	// swept into the figure. The assertions below pin the new rule — drafts are excluded — and then
831	// demonstrate it dynamically: SENDING a draft (the only way its money becomes owed) grows the owed
832	// total by exactly that invoice's amount.
833	//
834	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
835	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
836	// `invoices` honours { id, amount, projectId, status }.
837	import { test, expect, type Page, type Locator } from '@playwright/test';
838	import { resetAndSeed } from '../support/seed';
839	
840	// A money figure may be rendered bare (550) or dressed up ("$550.00"). Assert the figure CARRIES
841	// the expected number as a standalone token, so the test binds to the meaning rather than to one
842	// presentation. The surrounding (^|\D)…(\D|$) keeps a smaller number from matching inside a larger
843	// one (550 must not satisfy a check for 50, nor 55 match inside 550).
844	const asToken = (n: number) => new RegExp(`(^|\\D)${n}(\\D|$)`);
845	const shows = (cell: Locator, n: number) => expect(cell).toContainText(asToken(n));
846	const hides = (cell: Locator, n: number) => expect(cell).not.toContainText(asToken(n));
847	
848	const SENT = /\bsent\b/i;
849	
850	const outstanding = (page: Page) => page.getByTestId('dashboard-outstanding-total');
851	
852	// Reach the dashboard the way a user would — follow its nav link from the home screen — rather than
853	// pinning the dashboard's URL.
854	async function openDashboard(page: Page): Promise<void> {
855	  await page.goto('/');
856	  const nav = page.getByTestId('nav-dashboard');
857	  await expect(nav).toBeVisible();
858	  await nav.click();
859	  await expect(page.getByTestId('dashboard-page')).toBeVisible();
860	  await expect(page.getByTestId('dashboard')).toBeVisible();
861	}
