951	// Acceptance test for the change request:
952	//   "Show money properly everywhere. Use a dollar sign and cents, like $100.00."
953	//
954	// Every value the app surfaces as MONEY must be shown "properly": a leading dollar sign and the
955	// amount written to two decimal places of cents, exactly as the request illustrates with $100.00.
956	// The app surfaces money in three places, each behind a stable anchor:
957	//   - invoice-amount              — an invoice's amount, on a project's detail page
958	//   - project-invoices-total      — what a project's invoices add up to
959	//   - dashboard-outstanding-total — how much money is still owed, on the dashboard
960	// A bare number (100.00) or one missing its cents (100) is NOT "money shown properly", so each
961	// assertion below requires the dollar sign AND the two cents digits.
962	//
963	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
964	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
965	// `invoices` honours { id, amount, projectId, status }.
966	import { test, expect, type Page, type Locator } from '@playwright/test';
967	import { resetAndSeed } from '../support/seed';
968	
969	// "Money shown properly": a dollar sign, the whole-dollar amount, a decimal point and exactly two
970	// cents digits — e.g. $100.00. Thousands grouping ($1,200.00) is allowed but not required, so the
971	// matcher does not pin one grouping style; what it does require — and what this change is about — is
972	// the leading "$" and the trailing ".00". The amounts seeded below all stay under a thousand, so
973	// grouping never actually arises. The match is anchored (^…$) so the cell carries the money value
974	// and nothing else.
975	const money = (dollars: number): RegExp => {
976	  const whole = Math.trunc(dollars).toLocaleString('en-US').replace(/,/g, ',?');
977	  return new RegExp(`^\\$${whole}\\.00$`);
978	};
979	
